"bt": "<p><sup>8</sup>내 아들아, 네 아버지의 훈계를 듣고, 네 어머니의 가르침을 저버리지 마라.</p><p><sup>9</sup>그것은 네 머리에 쓸 아름다운 화관이요, 네 목에 걸 목걸이다.</p><p><sup>10</sup>내 아들아, 죄인들이 너를 꾀어도 따라가지 마라.</p><p><sup>11</sup>그들이 이렇게 말할 것이다. “우리와 함께 가자. 숨어 있다가 피를 흘리자. 죄 없는 사람을 까닭 없이 노리고 있다가,</p><p><sup>12</sup>음부가 삼키듯 그들을 산 채로 삼키고, 구덩이로 내려가는 사람처럼 통째로 삼키자.</p><p><sup>13</sup>온갖 값진 재물을 얻고, 빼앗은 것으로 우리 집을 가득 채우자.</p><p><sup>14</sup>너도 우리와 한패가 되어 제비를 뽑자. 우리 모두 돈주머니 하나를 함께 쓰자.”</p><p><sup>15</sup>내 아들아, 그들과 함께 그 길로 다니지 말고, 그들이 다니는 길에 발을 들여놓지 마라.</p><p><sup>16</sup>그들의 발은 악한 일을 하러 달려가고, 피를 흘리는 데 빠르다.</p><p><sup>17</sup>새가 보는 앞에서 그물을 치는 것은 헛된 일이다.</p><p><sup>18</sup>그런데 그들은 제 피를 흘리려고 숨어 기다리고, 제 목숨을 노리고 엎드려 있는 셈이다.</p><p><sup>19</sup>부당한 이익을 탐내는 사람의 길이 다 이러하다. 그런 욕심은 그것을 가진 사람의 목숨을 빼앗는다.</p>"
