"bt": "<p><sup>14</sup>악한 사람들의 길에 들어서지 말고, 나쁜 사람들의 길로 걸어가지 마라.</p><p><sup>15</sup>그 길을 피하여라. 그리로 지나가지 마라. 그 길에서 돌아서서 지나가 버려라.</p><p><sup>16</sup>그들은 악한 일을 하지 않으면 잠을 이루지 못하고, 누군가를 넘어뜨리지 않으면 잠이 달아나는 사람들이다.</p><p><sup>17</sup>그들은 악으로 얻은 빵을 먹고, 폭력으로 얻은 포도주를 마신다.</p><p><sup>18</sup>의인의 길은 동틀 녘의 빛과 같아서, 한낮이 될 때까지 점점 더 밝아진다.</p><p><sup>19</sup>악인의 길은 깊은 어둠과 같아서, 그들은 무엇에 걸려 넘어지는지도 알지 못한다.</p>"
