"bt": "<p><sup>20</sup>내 아들아, 네 아버지의 명령을 지키고, 네 어머니의 가르침을 버리지 마라.</p><p><sup>21</sup>그것을 늘 네 마음에 묶어 두고, 네 목에 걸어라.</p><p><sup>22</sup>네가 다닐 때에 그것이 너를 이끌고, 네가 누울 때에 너를 지키며, 네가 깨어나면 너에게 말을 건넬 것이다.</p><p><sup>23</sup>명령은 등불이요 가르침은 빛이며, 훈계하는 꾸지람은 생명의 길이다.</p><p><sup>24</sup>그것이 너를 지켜서 악한 여자에게서, 낯선 여자의 매끄러운 혀에서 너를 보호할 것이다.</p><p><sup>25</sup>네 마음에 그 여자의 아름다움을 탐내지 말고, 그 여자의 눈짓에 홀리지 마라.</p><p><sup>26</sup>음란한 여자 때문에 사람은 빵 한 조각만 남게 되고, 남의 아내는 귀한 생명을 사냥한다.</p><p><sup>27</sup>사람이 불을 품에 품고서 어찌 그 옷이 타지 않겠느냐?</p><p><sup>28</sup>사람이 숯불 위를 걸으면서 어찌 그 발이 데지 않겠느냐?</p><p><sup>29</sup>이웃의 아내와 함께 자는 사람도 그러하니, 그 여자를 건드리는 사람은 누구도 벌을 면하지 못한다.</p><p><sup>30</sup>도둑이 굶주려서 배를 채우려고 훔쳤다면, 사람들이 그를 업신여기지는 않는다.</p><p><sup>31</sup>그러나 들키면 일곱 배로 갚아야 하고, 자기 집 재산을 다 내놓아야 한다.</p><p><sup>32</sup>남의 아내와 간음하는 사람은 생각이 모자란 사람이니, 그렇게 하는 사람은 자기 자신을 망친다.</p><p><sup>33</sup>그는 매를 맞고 수치를 당하며, 그 부끄러움은 씻어지지 않는다.</p><p><sup>34</sup>질투는 남편을 분노하게 하니, 그가 원수를 갚는 날에는 사정을 보아주지 않는다.</p><p><sup>35</sup>그는 어떤 보상도 받아들이지 않고, 아무리 많은 선물을 주어도 마음을 돌리지 않는다.</p>"
