"bt": "<p><sup>1</sup>지혜가 부르고 있지 않느냐? 깨달음이 소리를 높이고 있지 않느냐?</p><p><sup>2</sup>지혜가 길가의 높은 곳에, 길이 만나는 곳에 서 있고,</p><p><sup>3</sup>성문 곁에서, 성읍 어귀에서, 들어오는 문들에서 외친다.</p><p><sup>4</sup>“사람들아, 내가 너희를 부른다. 내 목소리를 모든 사람에게 높인다.</p><p><sup>5</sup>어리석은 사람들아, 슬기를 깨달아라. 미련한 사람들아, 마음으로 깨달아라.</p><p><sup>6</sup>들어라. 내가 귀한 것을 말하고, 내 입술을 열어 바른 것을 말하겠다.</p><p><sup>7</sup>내 입은 진실을 말하고, 내 입술은 악을 싫어한다.</p><p><sup>8</sup>내 입의 말은 모두 의로워서, 그 가운데 비뚤어지거나 구부러진 것이 없다.</p><p><sup>9</sup>깨달은 사람에게는 그 모든 말이 분명하고, 지식을 얻은 사람에게는 바르다.</p><p><sup>10</sup>은 대신 내 훈계를 받고, 순금보다 지식을 택하여라.</p><p><sup>11</sup>지혜는 진주보다 낫고, 사람이 바라는 어떤 것도 지혜와 견줄 수 없다.”</p>"
