"bt": "<p><sup>12</sup>“나 지혜는 슬기와 함께 살고, 지식과 분별을 찾아 얻는다.</p><p><sup>13</sup>여호와를 경외하는 것은 악을 미워하는 것이다. 나는 교만과 거만과 악한 행실과 비뚤어진 입을 미워한다.</p><p><sup>14</sup>나에게는 계획과 참된 지혜가 있다. 나는 깨달음이고, 나에게는 힘이 있다.</p><p><sup>15</sup>나로 말미암아 왕들이 다스리고, 통치자들이 바른 법을 세운다.</p><p><sup>16</sup>나로 말미암아 지도자들과 귀족들, 곧 세상을 바르게 다스리는 모든 사람이 다스린다.</p><p><sup>17</sup>나를 사랑하는 사람을 나도 사랑하고, 나를 간절히 찾는 사람이 나를 만난다.</p><p><sup>18</sup>부와 영예가 나에게 있고, 오래가는 재물과 의로움도 나에게 있다.</p><p><sup>19</sup>내 열매는 금이나 순금보다 낫고, 내가 주는 소득은 좋은 은보다 낫다.</p><p><sup>20</sup>나는 의로운 길을 걷고, 공평한 길 한가운데로 다닌다.</p><p><sup>21</sup>그래서 나를 사랑하는 사람에게 재산을 물려주고, 그들의 곳간을 가득 채워 준다.”</p>"
