"bt": "<p><sup>22</sup>“여호와께서 그 일을 시작하실 때에, 오래전 그분이 무엇을 지으시기 전에 나를 가지고 계셨다.</p><p><sup>23</sup>영원 전부터, 맨 처음부터, 땅이 생기기 전부터 내가 세움을 받았다.</p><p><sup>24</sup>깊은 바다가 아직 없고, 물이 넘치는 샘들도 없을 때에 내가 태어났다.</p><p><sup>25</sup>산들이 아직 자리를 잡기 전에, 언덕들이 생기기 전에 내가 태어났다.</p><p><sup>26</sup>그분이 땅도 들도, 세상의 첫 흙덩이도 아직 만들지 않으셨을 때였다.</p><p><sup>27</sup>그분이 하늘을 세우실 때에, 깊은 바다 위에 둥근 테를 그으실 때에 내가 거기 있었다.</p><p><sup>28</sup>그분이 위로 구름을 굳게 하시고, 깊은 바다의 샘들을 힘 있게 하실 때에,</p><p><sup>29</sup>바다에 한계를 정하여 물이 그분의 명령을 넘지 못하게 하시고, 땅의 기초를 정하실 때에</p><p><sup>30</sup>나는 그분 곁에서 솜씨 있는 일꾼으로 있으면서, 날마다 그분의 기쁨이 되었고, 언제나 그분 앞에서 즐거워하였다.</p><p><sup>31</sup>그분이 지으신 땅에서 즐거워하고, 사람들과 함께하는 것을 기뻐하였다.”</p>"
