"bt": "<p><sup>28</sup>의인의 소망은 기쁨으로 이어지지만, 악인의 기대는 사라져 버린다.</p><p><sup>29</sup>여호와의 길은 흠 없는 사람에게는 피난처가 되지만, 악한 일을 하는 사람에게는 멸망이 된다.</p><p><sup>30</sup>의인은 영원히 흔들리지 않지만, 악인은 이 땅에서 살지 못한다.</p><p><sup>31</sup>의인의 입에서는 지혜가 열매처럼 맺히지만, 비뚤어진 혀는 잘려 나간다.</p><p><sup>32</sup>의인의 입술은 기쁘게 하는 말을 알지만, 악인의 입은 비뚤어진 말만 한다.</p>"
