"bt": "<p><sup>8</sup>슬기로운 사람의 지혜는 자기 길을 깨닫는 것이고, 어리석은 사람의 어리석음은 속임수다.</p><p><sup>9</sup>어리석은 사람은 죄를 비웃지만, 정직한 사람들 사이에는 호의가 있다.</p><p><sup>10</sup>마음의 괴로움은 자기만 알고, 마음의 기쁨도 다른 사람이 함께 나누지 못한다.</p><p><sup>11</sup>악인의 집은 무너지지만, 정직한 사람의 장막은 번성한다.</p><p><sup>12</sup>어떤 길은 사람이 보기에 바른 것 같지만, 결국은 죽음에 이르는 길이다.</p><p><sup>13</sup>웃고 있어도 마음이 아플 수 있고, 기쁨의 끝에도 슬픔이 있다.</p><p><sup>14</sup>마음이 빗나간 사람은 자기 행위의 결과를 실컷 받고, 선한 사람도 자기 행위의 열매를 받는다.</p>"
