"bt": "<p><sup>15</sup>어리석은 사람은 아무 말이나 다 믿지만, 슬기로운 사람은 자기 걸음을 잘 살핀다.</p><p><sup>16</sup>지혜로운 사람은 조심하여 악을 피하지만, 어리석은 사람은 함부로 행동하면서도 자신만만하다.</p><p><sup>17</sup>화를 잘 내는 사람은 어리석은 일을 저지르고, 악한 꾀를 꾸미는 사람은 미움을 받는다.</p><p><sup>18</sup>어리석은 사람은 어리석음을 물려받지만, 슬기로운 사람은 지식으로 면류관을 쓴다.</p><p><sup>19</sup>악한 사람은 선한 사람 앞에 엎드리고, 악인은 의인의 문 앞에 엎드린다.</p><p><sup>20</sup>가난한 사람은 이웃에게도 미움을 받지만, 부자에게는 친구가 많다.</p><p><sup>21</sup>이웃을 업신여기는 사람은 죄를 짓는 것이고, 가난한 사람을 불쌍히 여기는 사람은 복이 있다.</p>"
