"bt": "<p><sup>25</sup>어떤 길은 사람이 보기에 바른 것 같지만, 결국은 죽음에 이르는 길이다.</p><p><sup>26</sup>일하는 사람은 배가 고파서 애써 일하니, 그의 입이 그를 재촉하기 때문이다.</p><p><sup>27</sup>불량한 사람은 악을 파내고, 그 입술에는 타는 불 같은 것이 있다.</p><p><sup>28</sup>비뚤어진 사람은 다툼을 퍼뜨리고, 남의 말을 옮기는 사람은 친한 친구 사이를 갈라놓는다.</p><p><sup>29</sup>폭력을 휘두르는 사람은 이웃을 꾀어서 좋지 않은 길로 이끈다.</p><p><sup>30</sup>눈을 감는 사람은 비뚤어진 일을 꾸미고, 입술을 꼭 다무는 사람은 악을 이룬다.</p>"
