"bt": "<p><sup>15</sup>게으름은 사람을 깊이 잠들게 하고, 게으른 사람은 굶주린다.</p><p><sup>16</sup>계명을 지키는 사람은 자기 목숨을 지키지만, 자기 길을 소홀히 하는 사람은 죽는다.</p><p><sup>17</sup>가난한 사람을 불쌍히 여기는 것은 여호와께 빌려 드리는 것이니, 그분께서 그 선행을 갚아 주신다.</p><p><sup>18</sup>아직 희망이 있을 때 네 아들을 훈계하여라. 그러나 그를 죽일 마음은 품지 마라.</p><p><sup>19</sup>화를 몹시 내는 사람은 벌을 받는다. 네가 그를 건져 주면 또다시 건져 주어야 할 것이다.</p><p><sup>20</sup>조언을 듣고 훈계를 받아들여라. 그러면 마침내 지혜롭게 될 것이다.</p><p><sup>21</sup>사람의 마음에는 계획이 많아도, 끝까지 서는 것은 여호와의 뜻뿐이다.</p>"
