"bt": "<p><sup>22</sup>사람은 인자함 때문에 사랑을 받으니, 가난한 사람이 거짓말쟁이보다 낫다.</p><p><sup>23</sup>여호와를 경외하면 생명에 이르니, 그런 사람은 만족하게 살고 재앙을 만나지 않는다.</p><p><sup>24</sup>게으른 사람은 손을 그릇에 넣고도, 입으로 가져가기조차 귀찮아한다.</p><p><sup>25</sup>거만한 사람을 때리면 어리석은 사람도 조심하게 되고, 깨달은 사람을 꾸짖으면 그가 지식을 얻는다.</p><p><sup>26</sup>아버지를 구박하고 어머니를 쫓아내는 사람은 부끄러움과 수치를 불러오는 자식이다.</p><p><sup>27</sup>내 아들아, 지식의 말씀에서 벗어나게 하는 가르침은 듣지 마라.</p><p><sup>28</sup>불량한 증인은 공의를 비웃고, 악인의 입은 죄악을 삼킨다.</p><p><sup>29</sup>심판은 거만한 사람을 위해 마련되어 있고, 매는 어리석은 사람의 등을 위해 마련되어 있다.</p>"
