"bt": "<p><sup>9</sup>다투기 좋아하는 아내와 넓은 집에서 함께 사는 것보다, 지붕 한 귀퉁이에서 혼자 사는 것이 낫다.</p><p><sup>10</sup>악인의 마음은 악을 바라니, 그 이웃도 그에게서 은혜를 입지 못한다.</p><p><sup>11</sup>거만한 사람이 벌을 받으면 어리석은 사람이 지혜로워지고, 지혜로운 사람은 가르침을 받으면 지식을 얻는다.</p><p><sup>12</sup>의로우신 분은 악인의 집을 살피시고, 악인을 재앙에 빠뜨리신다.</p><p><sup>13</sup>가난한 사람이 부르짖는 소리에 귀를 막으면, 자기가 부르짖을 때에도 대답을 듣지 못한다.</p><p><sup>14</sup>몰래 주는 선물은 화를 가라앉히고, 품속에 넣어 주는 뇌물은 거센 분노를 누그러뜨린다.</p><p><sup>15</sup>바르게 행하는 것은 의인에게는 기쁨이지만, 악을 행하는 사람에게는 두려움이다.</p><p><sup>16</sup>깨달음의 길에서 벗어난 사람은 죽은 자들의 무리 가운데 머물게 된다.</p>"
