"bt": "<p><sup>17</sup>즐거움을 좋아하는 사람은 가난해지고, 술과 기름을 좋아하는 사람은 부자가 되지 못한다.</p><p><sup>18</sup>악인은 의인을 대신하여 값을 치르고, 배신하는 사람은 정직한 사람을 대신한다.</p><p><sup>19</sup>다투고 화내는 아내와 함께 사는 것보다, 광야에서 혼자 사는 것이 낫다.</p><p><sup>20</sup>지혜로운 사람의 집에는 귀한 보물과 기름이 있지만, 어리석은 사람은 그것을 다 삼켜 버린다.</p><p><sup>21</sup>의와 인자를 좇는 사람은 생명과 의로움과 영광을 얻는다.</p><p><sup>22</sup>지혜로운 사람은 용사들의 성에 올라가서, 그들이 믿는 요새를 무너뜨린다.</p><p><sup>23</sup>입과 혀를 지키는 사람은 자기 목숨을 재앙에서 지킨다.</p><p><sup>24</sup>교만하고 건방진 사람을 거만한 사람이라 부르니, 그는 넘치는 교만으로 행동한다.</p>"
