"bt": "<p><sup>22</sup>가난하다고 해서 약한 사람의 것을 빼앗지 말고, 성문 재판 자리에서 고난받는 사람을 짓밟지 마라.</p><p><sup>23</sup>여호와께서 그들의 송사를 맡아 주시고, 그들을 털어 간 사람의 목숨을 빼앗으실 것이다.</p><p><sup>24</sup>화를 잘 내는 사람과 사귀지 말고, 성질이 급한 사람과 함께 다니지 마라.</p><p><sup>25</sup>네가 그 행실을 배워서 네 목숨을 덫에 걸리게 할까 두렵다.</p><p><sup>26</sup>남과 손을 잡고 서약하지 말고, 남의 빚에 보증을 서지 마라.</p><p><sup>27</sup>갚을 것이 없으면, 네가 누운 침대까지 빼앗길 텐데 어찌 그렇게 하겠느냐?</p><p><sup>28</sup>네 조상들이 세워 놓은 옛 경계표를 옮기지 마라.</p><p><sup>29</sup>자기 일에 능숙한 사람을 보았느냐? 그런 사람은 왕 앞에 서고, 이름 없는 사람 앞에 서지 않는다.</p>"
