"bt": "<p><sup>26</sup>내 아들아, 네 마음을 나에게 주고, 네 눈으로 내 길을 즐거워하여라.</p><p><sup>27</sup>음란한 여자는 깊은 구덩이요, 낯선 여자는 좁은 우물이다.</p><p><sup>28</sup>그 여자는 강도처럼 숨어 기다리며, 사람들 가운데 배신하는 사람이 늘어나게 한다.</p><p><sup>29</sup>누구에게 재앙이 있느냐? 누구에게 근심이 있느냐? 누구에게 다툼이 있느냐? 누구에게 불평이 있느냐? 누구에게 까닭 없는 상처가 있느냐? 누구의 눈이 충혈되었느냐?</p><p><sup>30</sup>술자리에 오래 머무는 사람, 섞은 술을 찾아다니는 사람이다.</p><p><sup>31</sup>포도주가 붉게 잔에서 반짝이며 술술 넘어가더라도, 너는 그것을 쳐다보지도 마라.</p><p><sup>32</sup>그것이 끝내는 뱀처럼 물고, 독사처럼 쏠 것이다.</p><p><sup>33</sup>네 눈에는 이상한 것이 보이고, 네 마음은 엉뚱한 말을 쏟아 낼 것이다.</p><p><sup>34</sup>너는 바다 한가운데 누운 사람 같고, 돛대 꼭대기에 누운 사람 같을 것이다.</p><p><sup>35</sup>너는 말할 것이다. 사람들이 나를 때려도 아프지 않고, 나를 쳐도 아무 느낌이 없다. 언제 깨어날까? 다시 술을 찾아야겠다.</p>"
