"fun": "26:4와 26:5는 미련한 자에게 ‘대답하지 말라’와 ‘대답하라’를 나란히 놓고 각각 그 까닭을 붙입니다. 26:20의 ‘말장이’는 <span class=\"he\" lang=\"he\" dir=\"rtl\">נִרְגָּן</span>(니르간)으로, 16:28과 18:8에도 나오는 말입니다. 26:11은 베드로후서 2:22에 인용되어 있습니다.",
"plot": "미련한 자에게 영예가 적당하지 않음을 여름의 눈과 추수 때의 비에 견주며 시작합니다. 미련한 자를 두고 저는 자의 다리, 물매에 맨 돌, 토한 것을 도로 먹는 개 같은 비유가 이어집니다. 게으른 자는 길에 사자가 있다 하고 침상에서 구른다 하며, 나무가 다하면 불이 꺼지듯 말장이가 없으면 다툼이 쉰다고 합니다. 온유한 입술에 악한 마음을 품은 자를 말하고, 함정을 파는 자는 그것에 빠진다고 맺습니다.",
