"bt": "<p><sup>1</sup>여름에 눈이 오고 추수 때에 비가 오는 것처럼, 어리석은 사람에게는 영예가 어울리지 않는다.</p><p><sup>2</sup>참새가 떠돌고 제비가 날아가듯이, 까닭 없는 저주는 그 사람에게 닿지 않는다.</p><p><sup>3</sup>말에게는 채찍, 나귀에게는 재갈, 어리석은 사람의 등에는 매가 필요하다.</p><p><sup>4</sup>어리석은 사람의 어리석은 말에 맞추어 대답하지 마라. 너도 그와 같아질까 두렵다.</p><p><sup>5</sup>어리석은 사람의 어리석은 말에 맞게 대답하여라. 그가 스스로 지혜롭다고 여길까 두렵다.</p><p><sup>6</sup>어리석은 사람에게 소식을 맡겨 보내는 것은, 제 발을 자르고 해를 자초하는 것과 같다.</p><p><sup>7</sup>다리를 저는 사람의 다리가 힘없이 늘어져 있듯이, 어리석은 사람의 입에 있는 잠언도 그렇다.</p>"
