"bt": "<p><sup>8</sup>어리석은 사람에게 영예를 주는 것은, 물매에 돌을 묶어 두는 것과 같다.</p><p><sup>9</sup>어리석은 사람의 입에 있는 잠언은, 술 취한 사람의 손에 들린 가시나무와 같다.</p><p><sup>10</sup>솜씨 좋은 장인이 온갖 것을 만들어도, 어리석은 사람을 고용하는 것은 지나가는 아무나 고용하는 것과 같다.</p><p><sup>11</sup>개가 토한 것을 다시 먹듯이, 어리석은 사람은 어리석은 짓을 되풀이한다.</p><p><sup>12</sup>스스로 지혜롭다고 여기는 사람을 보았느냐? 그런 사람보다 어리석은 사람에게 오히려 더 희망이 있다.</p>"
