"bt": "<p><sup>7</sup>배부른 사람은 꿀도 싫어하지만, 배고픈 사람에게는 쓴 것도 달다.</p><p><sup>8</sup>고향을 떠나 떠도는 사람은 둥지를 떠나 헤매는 새와 같다.</p><p><sup>9</sup>기름과 향이 마음을 즐겁게 하듯이, 친구의 진심 어린 조언도 그렇게 달콤하다.</p><p><sup>10</sup>네 친구와 네 아버지의 친구를 버리지 마라. 어려움을 당했을 때 형제의 집을 찾아가지 마라. 가까운 이웃이 먼 형제보다 낫다.</p><p><sup>11</sup>내 아들아, 지혜로워져서 내 마음을 기쁘게 하여라. 그러면 나를 헐뜯는 사람에게 내가 대답할 수 있을 것이다.</p><p><sup>12</sup>슬기로운 사람은 재앙을 보면 숨지만, 어리석은 사람은 그대로 나아가다가 해를 입는다.</p><p><sup>13</sup>남의 보증을 선 사람에게서는 그 옷을 잡혀 두어라. 낯선 사람의 보증을 섰다면 그 몸을 담보로 잡아라.</p><p><sup>14</sup>이른 아침에 큰 소리로 이웃을 축복하면, 그것을 도리어 저주로 여길 것이다.</p>"
