"bt": "<p><sup>1</sup>르무엘 왕의 말이니, 그의 어머니가 그를 가르친 말이다.</p><p><sup>2</sup>내 아들아, 무엇을 말해 줄까? 내 태에서 난 아들아, 무엇을 말해 줄까? 서원하여 얻은 아들아, 무엇을 말해 줄까?</p><p><sup>3</sup>네 힘을 여자들에게 쏟지 말고, 왕들을 망하게 하는 일에 네 길을 내주지 마라.</p><p><sup>4</sup>르무엘아, 왕에게는 포도주를 마시는 것이 어울리지 않고, 통치자에게는 독한 술을 찾는 것이 어울리지 않는다.</p><p><sup>5</sup>술을 마시고 법을 잊어버려, 고난받는 사람들의 재판을 굽게 할까 두렵다.</p><p><sup>6</sup>독한 술은 죽어 가는 사람에게 주고, 포도주는 마음이 괴로운 사람에게 주어라.</p><p><sup>7</sup>그는 마시고 자기 가난을 잊고, 다시는 자기 고통을 기억하지 않을 것이다.</p><p><sup>8</sup>말 못 하는 사람을 위해, 버림받은 모든 사람의 송사를 위해 입을 열어라.</p><p><sup>9</sup>입을 열어 공정하게 재판하고, 가난하고 궁핍한 사람의 권리를 지켜 주어라.</p>"
